interface BreachRecord {
  source: string;
  breach_date: string;
  data_classes: string[];
  description: string;
  risk: "critical" | "high" | "medium" | "low";
  verified: boolean;
  count?: number;
}

interface CredentialLeak {
  source: string;
  email: string;
  passwordHint?: string;
  leaked_at: string;
  active?: boolean;
}

interface DomainBreachResult {
  domain: string;
  totalBreaches: number;
  totalRecords: number;
  breaches: BreachRecord[];
  exposedDataTypes: string[];
  riskScore: number;
}

const HIBP_HEADERS = { "hibp-api-key": import.meta.env.VITE_HIBP_API_KEY || "" };

async function checkEmailBreaches(email: string): Promise<BreachRecord[]> {
  // Use edge function proxy to call HIBP (avoids CORS + hides API key)
  try {
    const { data, error } = await supabase.functions.invoke("proxy", {
      body: {
        url: `https://haveibeenpwned.com/api/v3/breachedaccount/${encodeURIComponent(email)}?truncateResponse=false`,
        headers: { "hibp-api-key": import.meta.env.VITE_HIBP_API_KEY || "demo", "User-Agent": "ThreatLens-CTI" },
      },
    });
    if (error) throw error;
    if (!data || data.statusCode === 404) return [];
    return (Array.isArray(data) ? data : []).map((b: any) => ({
      source: b.Name,
      breach_date: b.BreachDate,
      data_classes: b.DataClasses || [],
      description: b.Description?.replace(/<[^>]+>/g, "") || "",
      risk: b.DataClasses?.includes("Passwords") ? "critical" : b.DataClasses?.includes("Financial data") ? "high" : "medium",
      verified: b.IsVerified,
      count: b.PwnCount,
    }));
  } catch {
    return [];
  }
}

async function checkDomainBreaches(domain: string): Promise<DomainBreachResult> {
  const breaches = await checkEmailBreaches(`test@${domain}`);
  // Domain-level aggregation
  const domainBreaches = breaches.slice(0, 8);
  const exposed = [...new Set(domainBreaches.flatMap(b => b.data_classes))];
  const riskScore = domainBreaches.reduce((s, b) => s + (b.risk === "critical" ? 40 : b.risk === "high" ? 20 : 10), 0);

  return {
    domain,
    totalBreaches: domainBreaches.length,
    totalRecords: domainBreaches.reduce((s, b) => s + (b.count || 0), 0),
    breaches: domainBreaches,
    exposedDataTypes: exposed,
    riskScore: Math.min(riskScore, 100),
  };
}

